tool_input.content:
$d = 'C:\Users\Administrator\Documents\deepseek-harness\default-workspace\.tmp-weekly\unz'
$f = $args[0]
[xml]$ss = Get-Content (Join-Path $d 'xl\sharedStrings.xml') -Encoding UTF8
$arr = @()
foreach ($si in $ss.sst.si) {
  if ($si.t) { if ($si.t -is [string]) { $arr += $si.t } else { $arr += $si.t.'#text' } }
  else { $arr += (($si.r | ForEach-Object { if ($_.t -is [string]) { $_.t } else { $_.t.'#text' } }) -join '') }
}
[xml]$sh = Get-Content (Join-Path $d "xl\worksheets\$f") -Encoding UTF8
foreach ($row in $sh.worksheet.sheetData.row) {
  $line = @()
  foreach ($c in $row.c) {
    $v = ''
    if ($c.t -eq 's') { $v = $arr[[int]$c.v] }
    elseif ($c.is) { $v = (($c.is.r | ForEach-Object { if ($_.t -is [string]) { $_.t } else { $_.t.'#text' } }) -join '') }
    elseif ($c.v) { $v = $c.v }
    if ($v -ne '' -and $null -ne $v) { $line += ("{0}=[{1}]" -f $c.r, $v) }
  }
  if ($line.Count -gt 0) { "R$($row.r): " + ($line -join ' | ') }
}
'---mergeCells---'
$sh.worksheet.mergeCells.mergeCell | ForEach-Object { $_.ref }

